sources={'export_comparator.py': '"""Export the already-frozen original comparator scores; no fitting or inference."""\nimport hashlib\nimport json\nfrom pathlib import Path\n\nimport numpy as np\nimport pandas as pd\n\nfrom compare_experiments import metrics\nfrom export_predictions import export\n\n\ndef run(folder, output, lock, expected_metrics):\n    folder, output = Path(folder), Path(output)\n    output.mkdir(parents=True, exist_ok=True)\n    config_path = folder / \'inference_config.json\'\n    config = json.loads(config_path.read_text())\n    for key, value in lock[\'config\'].items():\n        if config.get(key) != value:\n            raise ValueError(\'Original comparator configuration differs: \' + key)\n    for trial, expected in lock[\'checkpoints\'].items():\n        if hashlib.sha256((folder/trial/\'best_weights.pt\').read_bytes()).hexdigest() != expected:\n            raise ValueError(\'Original checkpoint changed: \' + trial)\n    manifest = pd.read_csv(folder/\'split_manifest.csv\').sort_values(\'sha256\').reset_index(drop=True)\n    cohort = manifest.loc[manifest.split == \'test\'].reset_index(drop=True)\n    if len(cohort) != 618 or cohort.patient.nunique() != 426 or cohort.sha256.duplicated().any():\n        raise ValueError(\'Original test cohort invalid\')\n    digest = hashlib.sha256(\'\\n\'.join(cohort.sha256).encode()).hexdigest()\n    if digest != \'c0de6a4a18c8c295d85551b5b8602410e2e26d173b8ab9f141e82cd6fdca9378\':\n        raise ValueError(\'Original test cohort digest differs\')\n    source = folder/\'test_predictions.csv\'\n    values = pd.read_csv(source).sort_values(\'sha256\').reset_index(drop=True)\n    if values.isna().any().any() or values.sha256.duplicated().any():\n        raise ValueError(\'Invalid original score table\')\n    for key in [\'sha256\', \'patient\']:\n        if not cohort[key].equals(values[key]): raise ValueError(\'Original score identity mismatch\')\n    if not np.array_equal(values.y_true, cohort.label): raise ValueError(\'Original labels differ\')\n    if not np.isfinite(values.probability).all() or not values.probability.between(0, 1).all():\n        raise ValueError(\'Invalid original score\')\n    if not np.array_equal(values.prediction, values.probability >= config[\'threshold\']):\n        raise ValueError(\'Original classifications differ from frozen rule\')\n    measured = metrics(values)\n    for key, expected in expected_metrics.items():\n        if abs(measured[key]-expected) > 1e-10: raise ValueError(\'Original summary mismatch: \' + key)\n    public = values[[\'sha256\', \'patient\', \'y_true\', \'probability\', \'prediction\']].copy()\n    public[\'threshold\'] = config[\'threshold\']\n    meta = export(public, output, \'public_original_320_test_predictions.csv\')\n    result = dict(status=\'passed\', original_kaggle_version=360888746, images=618, groups=426,\n                  checkpoint_hashes_verified=len(lock[\'checkpoints\']), frozen_configuration=lock[\'config\'],\n                  config_file_sha256=hashlib.sha256(config_path.read_bytes()).hexdigest(),\n                  source_prediction_file_sha256=hashlib.sha256(source.read_bytes()).hexdigest(),\n                  metrics=measured, public_prediction_exports={\'original_320\': meta},\n                  scope=\'Artifact export after outcomes were known. No fitting, inference, cutoff change or model selection. Scores are the saved original temperature-scaled scores, not raw sigmoid probabilities.\')\n    (output/\'comparator_export.json\').write_text(json.dumps(result,indent=2),encoding=\'utf-8\')\n    print(\'COMPARATOR_EXPORT_DONE\', json.dumps(result), flush=True)\n    return result\n', 'export_predictions.py': '"""Emit de-identified public-dataset prediction tables through bounded log blocks."""\nimport hashlib\nimport json\nfrom pathlib import Path\nimport re\n\n\ndef export(frame, output, filename):\n    if not re.fullmatch(r\'[a-z0-9_]+\\.csv\', filename): raise ValueError(\'Invalid export filename\')\n    if frame.isna().any().any() or frame.sha256.duplicated().any(): raise ValueError(\'Invalid prediction table\')\n    frame = frame.sort_values(\'sha256\').reset_index(drop=True)\n    payload = frame.to_csv(index=False, lineterminator=\'\\n\', float_format=\'%.17g\').encode(\'utf-8\')\n    path = Path(output) / filename\n    path.write_bytes(payload)\n    records = frame.to_dict(\'records\'); block_size = 50\n    meta = dict(filename=filename, rows=len(frame), columns=frame.columns.tolist(),\n                sha256=hashlib.sha256(payload).hexdigest(), blocks=(len(frame)+block_size-1)//block_size,\n                format=\'UTF-8 CSV, LF, no index, floats %.17g\',\n                scope=\'Public research-dataset pixel hashes, filename proxy groups, inherited labels and model scores; no image pixels or verified patient identity\')\n    print(\'PUBLIC_PREDICTION_TABLE\', json.dumps(meta), flush=True)\n    for index in range(meta[\'blocks\']):\n        print(\'PUBLIC_PREDICTION_BLOCK\', json.dumps(dict(filename=filename, index=index,\n              rows=records[index*block_size:(index+1)*block_size]), allow_nan=False), flush=True)\n    return meta\n', 'compare_experiments.py': '"""Paired descriptive comparison of frozen predictions; never fits thresholds."""\nimport argparse\nimport json\nfrom pathlib import Path\n\nimport numpy as np\nimport pandas as pd\nfrom sklearn.metrics import roc_auc_score, average_precision_score\n\n\ndef metrics(frame):\n    y = frame.y_true.to_numpy(dtype=int)\n    p = frame.probability.to_numpy(dtype=float)\n    pred = frame.prediction.to_numpy(dtype=int)\n    return {\n        \'auroc\': float(roc_auc_score(y, p)),\n        \'average_precision\': float(average_precision_score(y, p)),\n        \'accuracy\': float(np.mean(y == pred)),\n        \'sensitivity\': float(np.mean(pred[y == 1] == 1)),\n        \'specificity\': float(np.mean(pred[y == 0] == 0)),\n        \'brier_score\': float(np.mean((y - p) ** 2)),\n    }\n\n\ndef compare(baseline_dir, followup_dir, replicates=1000):\n    if replicates < 1:\n        raise ValueError(\'replicates must be positive\')\n    frames = []\n    for directory in (baseline_dir, followup_dir):\n        frame = pd.read_csv(Path(directory) / \'test_predictions.csv\')\n        required = {\'sha256\', \'patient\', \'y_true\', \'probability\', \'prediction\'}\n        if not required.issubset(frame.columns) or frame.sha256.duplicated().any():\n            raise ValueError(\'Missing fields or duplicate image hashes\')\n        if set(frame.y_true) != {0, 1} or not set(frame.prediction).issubset({0, 1}):\n            raise ValueError(\'Expected binary labels with both classes represented\')\n        if not np.isfinite(frame.probability).all() or not frame.probability.between(0, 1).all():\n            raise ValueError(\'Invalid probabilities\')\n        if frame.patient.isna().any() or frame.sha256.isna().any():\n            raise ValueError(\'Missing pairing or cluster identifiers\')\n        frames.append(frame.sort_values(\'sha256\').reset_index(drop=True))\n    a, b = frames\n    for column in (\'sha256\', \'patient\', \'y_true\'):\n        if not a[column].equals(b[column]):\n            raise ValueError(\'Test cohorts or labels differ: \' + column)\n    ma, mb = metrics(a), metrics(b)\n    groups = [np.flatnonzero(a.patient.to_numpy() == group) for group in a.patient.unique()]\n    rng = np.random.default_rng(42)\n    differences = []\n    for _ in range(replicates):\n        idx = np.concatenate([groups[i] for i in rng.integers(0, len(groups), len(groups))])\n        if a.iloc[idx].y_true.nunique() != 2:\n            continue\n        sa, sb = metrics(a.iloc[idx]), metrics(b.iloc[idx])\n        differences.append({key: sb[key] - sa[key] for key in sa})\n    if not differences:\n        raise ValueError(\'No bootstrap sample contained both classes\')\n    return {\n        \'status\': \'Exploratory paired comparison; original test results already inspected\',\n        \'direction\': \'followup minus baseline; lower is better for Brier score only\',\n        \'images\': len(a), \'filename_proxy_groups\': len(groups),\n        \'baseline\': ma, \'followup\': mb,\n        \'difference\': {key: mb[key] - ma[key] for key in ma},\n        \'paired_cluster_bootstrap_95ci\': {\n            key: np.percentile([d[key] for d in differences], [2.5, 97.5]).tolist()\n            for key in ma},\n        \'bootstrap_replicates\': len(differences),\n        \'limitations\': \'Filename groups are proxies. Intervals describe test sampling, not training variation, model selection uncertainty or external generalization. No multiplicity adjustment. Thresholds remain those saved by each experiment.\'\n    }\n\n\nif __name__ == \'__main__\':\n    parser = argparse.ArgumentParser(description=__doc__)\n    parser.add_argument(\'baseline\', type=Path)\n    parser.add_argument(\'followup\', type=Path)\n    parser.add_argument(\'--output\', type=Path, required=True)\n    parser.add_argument(\'--replicates\', type=int, default=1000)\n    args = parser.parse_args()\n    report = compare(args.baseline, args.followup, args.replicates)\n    args.output.parent.mkdir(parents=True, exist_ok=True)\n    args.output.write_text(json.dumps(report, indent=2))\n    print(json.dumps(report, indent=2))\n'}
